'use client';

import * as React from 'react';
import type { ToastAction, ToastOptions, ToastRecord } from './toast-store';

export type { ToastAction, ToastOptions, ToastRecord };

export type ToastContextValue = {
  toasts: ToastRecord[];
  toast: (options: ToastOptions) => string;
  dismiss: (id: string) => void;
};

const ToastContext = React.createContext<ToastContextValue | null>(null);

const DEFAULT_DURATION = 5000;

/**
 * Accessible app-level notifications. Toasts render into a polite live
 * region so screen readers announce them without stealing focus, stack
 * newest-first, and auto-dismiss unless duration is 0.
 */
export function ToastProvider({ children, label = 'Notifications' }: { children: React.ReactNode; label?: string }) {
  const [toasts, setToasts] = React.useState<ToastRecord[]>([]);
  const timers = React.useRef(new Map<string, ReturnType<typeof setTimeout>>());

  const dismiss = React.useCallback((id: string) => {
    const timer = timers.current.get(id);
    if (timer) {
      clearTimeout(timer);
      timers.current.delete(id);
    }
    setToasts((current) => current.filter((entry) => entry.id !== id));
  }, []);

  const toast = React.useCallback(
    (options: ToastOptions) => {
      const id = `toast-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      setToasts((current) => [...current, { ...options, id }]);
      const duration = options.duration ?? DEFAULT_DURATION;
      if (duration > 0) {
        timers.current.set(
          id,
          setTimeout(() => dismiss(id), duration),
        );
      }
      return id;
    },
    [dismiss],
  );

  React.useEffect(() => {
    const pending = timers.current;
    return () => {
      for (const timer of pending.values()) clearTimeout(timer);
      pending.clear();
    };
  }, []);

  const value = React.useMemo(() => ({ toasts, toast, dismiss }), [toasts, toast, dismiss]);

  return (
    <ToastContext.Provider value={value}>
      {children}
      <ToastRegion toasts={toasts} onDismiss={dismiss} label={label} />
    </ToastContext.Provider>
  );
}

export function useToast(): ToastContextValue {
  const context = React.useContext(ToastContext);
  if (!context) throw new Error('useToast must be used within a <ToastProvider>.');
  return context;
}

function ToastRegion({
  toasts,
  onDismiss,
  label,
}: {
  toasts: ToastRecord[];
  onDismiss: (id: string) => void;
  label: string;
}) {
  return (
    <ol
      aria-label={label}
      className="fixed bottom-4 right-4 z-50 flex w-full max-w-sm flex-col gap-2"
    >
      {toasts.map((entry) => (
        <li key={entry.id} className="rounded-lg border border-border bg-card p-4 shadow-lg">
          <div role="status" className="flex items-start justify-between gap-3">
            <div>
              <p className="text-sm font-semibold">{entry.title}</p>
              {entry.description && <p className="mt-1 text-sm text-muted-foreground">{entry.description}</p>}
            </div>
            <button
              type="button"
              onClick={() => onDismiss(entry.id)}
              aria-label={`Dismiss ${entry.title}`}
              className="rounded p-1 text-muted-foreground hover:text-foreground"
            >
              ✕
            </button>
          </div>
          {entry.action && (
            <button
              type="button"
              onClick={() => {
                entry.action?.onClick();
                onDismiss(entry.id);
              }}
              className="mt-2 text-sm font-medium text-primary hover:underline"
            >
              {entry.action.label}
            </button>
          )}
        </li>
      ))}
    </ol>
  );
}

'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';
import {
  getToastServerSnapshot,
  getToastSnapshot,
  subscribeToToasts,
  toast as imperativeToast,
  type ToastRecord,
  type ToastVariant,
} from './toast-store';

export type ToasterPosition =
  | 'top-left'
  | 'top-center'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-center'
  | 'bottom-right';

export type ToasterProps = {
  /** Corner/edge the stack renders at. Default 'bottom-right'. */
  position?: ToasterPosition;
  /** Accessible name of the live region. Default 'Notifications'. */
  label?: string;
  /** Tint the toast surface with its status color (neutral by default). */
  richColors?: boolean;
};

const positionClasses: Record<ToasterPosition, string> = {
  'top-left': 'left-4 top-4 items-start',
  'top-center': 'left-1/2 top-4 -translate-x-1/2 items-center',
  'top-right': 'right-4 top-4 items-end',
  'bottom-left': 'bottom-4 left-4 items-start',
  'bottom-center': 'bottom-4 left-1/2 -translate-x-1/2 items-center',
  'bottom-right': 'bottom-4 right-4 items-end',
};

const richClasses: Record<ToastVariant, string> = {
  default: 'border-border bg-card',
  success: 'border-success/50 bg-success/10',
  error: 'border-destructive/50 bg-destructive/10',
  warning: 'border-warning/50 bg-warning/10',
  info: 'border-info/50 bg-info/10',
};

const dotClasses: Record<ToastVariant, string> = {
  default: 'bg-muted-foreground',
  success: 'bg-success',
  error: 'bg-destructive',
  warning: 'bg-warning',
  info: 'bg-info',
};

/**
 * Renders the imperative toast queue. Mount once near the app root:
 *
 *   <Toaster />
 *   toast.success('Saved')
 *
 * The region is a polite live region, so announcements don't steal focus.
 */
export function Toaster({ position = 'bottom-right', label = 'Notifications', richColors = false }: ToasterProps) {
  const entries = React.useSyncExternalStore(subscribeToToasts, getToastSnapshot, getToastServerSnapshot);

  return (
    <ol
      aria-label={label}
      className={cn('fixed z-[60] flex w-full max-w-sm flex-col gap-2', positionClasses[position])}
    >
      {entries.map((entry) => {
        const variant = entry.variant ?? 'default';
        return (
          <li
            key={entry.id}
            className={cn(
              'rounded-lg border p-4 shadow-lg',
              richColors ? richClasses[variant] : 'border-border bg-card',
            )}
          >
            <div role="status" className="flex items-start gap-3">
              <span aria-hidden="true" className={cn('mt-1 h-2 w-2 shrink-0 rounded-full', dotClasses[variant])} />
              <div className="min-w-0 flex-1">
                <p className="text-sm font-semibold">{entry.title}</p>
                {entry.description && <p className="mt-1 text-sm text-muted-foreground">{entry.description}</p>}
                {entry.action && (
                  <button
                    type="button"
                    onClick={() => {
                      entry.action?.onClick();
                      imperativeToast.dismiss(entry.id);
                    }}
                    className="mt-2 text-sm font-medium text-primary hover:underline"
                  >
                    {entry.action.label}
                  </button>
                )}
              </div>
              <button
                type="button"
                onClick={() => imperativeToast.dismiss(entry.id)}
                aria-label={`Dismiss ${entry.title}`}
                className="rounded p-1 text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                ✕
              </button>
            </div>
          </li>
        );
      })}
    </ol>
  );
}

export type { ToastRecord };

export { ToastProvider, useToast } from './Toast';
export type { ToastOptions, ToastRecord, ToastAction, ToastContextValue } from './Toast';
export { Toaster } from './Toaster';
export type { ToasterProps, ToasterPosition } from './Toaster';
export { toast } from './toast-store';
export type { ToastVariant } from './toast-store';

/**
 * Imperative toast store.
 *
 * Components can call `toast(...)` from anywhere — event handlers, data
 * layers, async catch blocks — without threading a hook through the tree.
 * `<Toaster />` subscribes to this store and renders the queue. The
 * provider/hook API in Toast.tsx remains for tree-scoped usage.
 */

export type ToastVariant = 'default' | 'success' | 'error' | 'warning' | 'info';

export type ToastAction = {
  label: string;
  onClick: () => void;
};

export type ToastOptions = {
  title: string;
  description?: string;
  action?: ToastAction;
  variant?: ToastVariant;
  /** Auto-dismiss delay in ms; 0 keeps the toast until dismissed. Default 5000. */
  duration?: number;
};

export type ToastRecord = ToastOptions & { id: string };

type Listener = (toasts: readonly ToastRecord[]) => void;

const DEFAULT_DURATION = 5000;

let toasts: readonly ToastRecord[] = [];
const EMPTY: readonly ToastRecord[] = [];
const listeners = new Set<Listener>();
const timers = new Map<string, ReturnType<typeof setTimeout>>();

function emit() {
  for (const listener of listeners) listener(toasts);
}

function dismiss(id: string) {
  const timer = timers.get(id);
  if (timer) {
    clearTimeout(timer);
    timers.delete(id);
  }
  toasts = toasts.filter((entry) => entry.id !== id);
  emit();
}

function show(options: ToastOptions): string {
  const id = `toast-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  toasts = [...toasts, { ...options, id }];
  emit();

  const duration = options.duration ?? DEFAULT_DURATION;
  if (duration > 0) {
    timers.set(
      id,
      setTimeout(() => dismiss(id), duration),
    );
  }
  return id;
}

type ToastFunction = ((options: ToastOptions) => string) & {
  success: (title: string, description?: string) => string;
  error: (title: string, description?: string) => string;
  warning: (title: string, description?: string) => string;
  info: (title: string, description?: string) => string;
  dismiss: (id?: string) => void;
  clear: () => void;
};

/**
 * Fire a toast from anywhere. Variant helpers mirror the sonner/Radix
 * shape most codebases already call:
 *
 *   toast.success('Saved')
 *   toast.error('Upload failed', 'Check your connection')
 *   toast({ title: 'Heads up', duration: 0 })
 */
export const toast: ToastFunction = Object.assign(
  (options: ToastOptions) => show({ ...options, variant: options.variant ?? 'default' }),
  {
    success: (title: string, description?: string) => show({ title, description, variant: 'success' }),
    error: (title: string, description?: string) => show({ title, description, variant: 'error' }),
    warning: (title: string, description?: string) => show({ title, description, variant: 'warning' }),
    info: (title: string, description?: string) => show({ title, description, variant: 'info' }),
    dismiss: (id?: string) => {
      if (id) {
        dismiss(id);
        return;
      }
      for (const entry of [...toasts]) dismiss(entry.id);
    },
    clear: () => {
      for (const entry of [...toasts]) dismiss(entry.id);
    },
  },
);

/** Subscribe to the queue (used by `<Toaster />`). */
export function subscribeToToasts(listener: Listener): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Current queue; the reference is stable between mutations. */
export function getToastSnapshot(): readonly ToastRecord[] {
  return toasts;
}

/** SSR-safe snapshot — always empty (toasts only exist client-side). */
export function getToastServerSnapshot(): readonly ToastRecord[] {
  return EMPTY;
}

